# Let me focus on the actual differences in positions
inputs = ['xyhid', 'wky', 'kvvfy', 'hwiffe', 'gbgd']
outputs = ['xyhid', 'wky', 'kdidify', 'hwiffgxb', 'gyjgd']

print("Character-by-character differences:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"\n{i}: '{inp}' -> '{out}'")

    # Find all positions where characters differ
    diff_positions = []
    min_len = min(len(inp), len(out))

    for j in range(min_len):
        if inp[j] != out[j]:
            diff_positions.append((j, inp[j], out[j]))

    # Check for length differences
    if len(inp) != len(out):
        if len(inp) > len(out):
            # Characters deleted
            for j in range(len(out), len(inp)):
                diff_positions.append((j, inp[j], None))
        else:
            # Characters added
            for j in range(len(inp), len(out)):
                diff_positions.append((j, None, out[j]))

    for pos, old_char, new_char in diff_positions:
        if old_char is None:
            print(f"  Pos {pos}: INSERT '{new_char}'")
        elif new_char is None:
            print(f"  Pos {pos}: DELETE '{old_char}'")
        else:
            print(f"  Pos {pos}: '{old_char}' -> '{new_char}'")

